INSERT INTO `email_outbox` VALUES (1,'slamit707@gmail.com','Verify your Utility Billing email address','Hi Mark,\n\nThanks for signing up for Utility Billing. Confirm your email address by opening this link:\nhttp://utility-billing.test/auth/verify?token=4O8H3QhR5OyPEjLi1KbS1WPGnsjyWApronbXGmuGW7x\n\nThe link expires in 24 hours. If you didn\'t create an account, you can ignore this email.','http://utility-billing.test/auth/verify?token=4O8H3QhR5OyPEjLi1KbS1WPGnsjyWApronbXGmuGW7x','2026-10-13 22:54:00'),(2,'sags775@gmail.com','You\'re invited to Utility Billing','Hi Mark Biz,\n\nBiz has invited you to Utility Billing. Open this link to verify your email address and create your username and password:\nhttp://utility-billing.test/accept-invitation?token=CQcXf2kIu7rlQ03pshrodkLzlJH8xX24jrPZcxY4zhl\n\nThe link expires in 7 days. If you weren\'t expecting this, you can ignore this email.','http://utility-billing.test/accept-invitation?token=CQcXf2kIu7rlQ03pshrodkLzlJH8xX24jrPZcxY4zhl','2026-10-13 23:13:38');
